import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

const Etudiants = () => {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem("token");
        
        // CORRECTION : Utiliser la bonne route /api/students
        const response = await fetch("http://localhost:5000/api/students", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        if (response.ok) {
          const data = await response.json();
          // CORRECTION : Accéder à data.students au lieu de data directement
          setStudents(data.students || []);
        } else {
          console.error("Erreur réponse:", response.status);
          setStudents([]);
        }
      } catch (error) {
        console.error("Erreur fetch étudiants :", error);
        setStudents([]);
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  const handleCreateStudent = () => {
    navigate("/creer-student");
  };

  if (loading) return <p style={{ padding: "2rem" }}>Chargement des étudiants...</p>;

  return (
    <div style={{ padding: "2rem" }}>
      <h1>Liste des Étudiants</h1>
      <button 
        onClick={handleCreateStudent} 
        style={{ margin: "1rem 0", padding: "0.6rem 1.2rem", borderRadius: "8px", background: "#2563eb", color: "white", border: "none", cursor: "pointer" }}
      >
        ➕ Créer un nouvel étudiant
      </button>

      {students.length === 0 ? (
        <p>Aucun étudiant inscrit pour le moment.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "1rem" }}>
          <thead>
            <tr>
              <th style={thStyle}>ID</th>
              <th style={thStyle}>Nom</th>
              <th style={thStyle}>Email</th>
              <th style={thStyle}>Classe</th>
              <th style={thStyle}>Rôle</th>
            </tr>
          </thead>
          <tbody>
            {students.map((s) => (
              <tr key={s.id}>
                <td style={tdStyle}>{s.id}</td>
                <td style={tdStyle}>{s.nom}</td>
                <td style={tdStyle}>{s.email}</td>
                <td style={tdStyle}>{s.class_name || "Non attribuée"}</td>
                <td style={tdStyle}>{s.role}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

const thStyle = { borderBottom: "2px solid #ccc", padding: "0.8rem", textAlign: "left", background: "#f1f5f9" };
const tdStyle = { borderBottom: "1px solid #e2e8f0", padding: "0.8rem" };

export default Etudiants;
